let drag = null;
const yToMin = (col, y) => { const r = col.getBoundingClientRect(), mins = H0 * 60 + (y - r.top) / HH * 60; return Math.max(H0 * 60, Math.min(H1 * 60, Math.round(mins / 15) * 15)); };
